class Solution {
    public int[] minCosts(int[] cost) {
        int[] ans = new int[cost.length];
        int m = Integer.MAX_VALUE;
        for (int i = 0; i < cost.length; i++) {
            m = Math.min(m, cost[i]);
            ans[i] = m;
        }
        return ans;
    }
}

